function loadRecords() {
  const accountId = arguments[0] || loadActiveAccountId();
  try {
    const scoped = localStorage.getItem(`cosmos-records-${accountId}`);
    if (scoped) return normalizeRecords(JSON.parse(scoped));
    const legacy = accountId === 'demo-learner' ? localStorage.getItem('cosmos-records') : null;
    return normalizeRecords(legacy ? JSON.parse(legacy) : accountId === 'demo-learner' ? seedRecords : []);
  } catch { return normalizeRecords(accountId === 'demo-learner' ? seedRecords : []); }
}
function loadAssistantMessages() { const accountId = loadActiveAccountId(); if (accountId === 'demo-learner') return []; try { return JSON.parse(localStorage.getItem(`cosmos-assistant-${accountId}`)) || []; } catch { return []; } }
function loadQuestObjective() { const accountId = loadActiveAccountId(); try { const id = localStorage.getItem(`cosmos-quest-${accountId}`); return objectives.some(item => item.id === id) ? id : 'BIO-04'; } catch { return 'BIO-04'; } }
function loadLlmConsent() { try { return localStorage.getItem(`cosmos-llm-consent-${loadActiveAccountId()}`) === 'true'; } catch { return false; } }
function loadLlmAnalysis() { try { return JSON.parse(localStorage.getItem(`cosmos-llm-analysis-${loadActiveAccountId()}`)) || null; } catch { return null; } }
function defaultDigitalId(accountId = loadActiveAccountId()) { return { handle: `COS-${accountId.slice(-6).toUpperCase()}`, alias: '', avatar: '', createdAt: '', bridges: [] }; }
function loadDigitalId(accountId = loadActiveAccountId()) { if (accountId === 'demo-learner') return defaultDigitalId(accountId); try { return { ...defaultDigitalId(accountId), ...(JSON.parse(localStorage.getItem(`cosmos-digital-id-${accountId}`)) || {}) }; } catch { return defaultDigitalId(accountId); } }
function loadAvatarState(accountId = loadActiveAccountId()) { const fallback = { mode: 'idle', objectiveId: 'BIO-04', lastEvent: 'SESSION_READY', message: lumaAvatarModes.idle.cue, updatedAt: '' }; try { return { ...fallback, ...(JSON.parse(localStorage.getItem(`cosmos-avatar-state-${accountId}`)) || {}) }; } catch { return fallback; } }
function loadAccounts() { try { return JSON.parse(localStorage.getItem('cosmos-accounts')) || seedAccounts; } catch { return seedAccounts; } }
function loadActiveAccountId() { try { const id = localStorage.getItem('cosmos-active-account'); return id || 'demo-learner'; } catch { return 'demo-learner'; } }
function currentAccount() { return state.accounts.find(account => account.id === state.accountId) || seedAccounts[0]; }
function visibleRecords() { return state.role === 'parent' && !state.shareConsent ? state.records.filter(record => record.demo) : state.records; }
function saveAccounts() { localStorage.setItem('cosmos-accounts', JSON.stringify(state.accounts)); queueServerSync(); }
function loadRole() { try { const role = localStorage.getItem('cosmos-role'); return role && roleProfiles[role] ? role : 'student'; } catch { return 'student'; } }
function currentRole() { return roleProfiles[state.role] || roleProfiles.student; }
function saveRole() { localStorage.setItem('cosmos-role', state.role); }
function saveRecords() { state.records = normalizeRecords(state.records); localStorage.setItem(`cosmos-records-${state.accountId}`, JSON.stringify(state.records)); queueServerSync(); }
function saveAssistantMessages() { localStorage.setItem(`cosmos-assistant-${state.accountId}`, JSON.stringify(state.assistantMessages.slice(-24))); queueServerSync(); }
function saveQuestObjective() { localStorage.setItem(`cosmos-quest-${state.accountId}`, state.questObjectiveId); queueServerSync(); }
function saveLlmConsent() { localStorage.setItem(`cosmos-llm-consent-${state.accountId}`, String(state.llmConsent)); queueServerSync(); }
function saveLlmAnalysis() { if (state.lastLlmAnalysis) localStorage.setItem(`cosmos-llm-analysis-${state.accountId}`, JSON.stringify(state.lastLlmAnalysis)); else localStorage.removeItem(`cosmos-llm-analysis-${state.accountId}`); queueServerSync(); }
function saveDigitalId() { localStorage.setItem(`cosmos-digital-id-${state.accountId}`, JSON.stringify(state.digitalId)); queueServerSync(); }
function saveAvatarState() { localStorage.setItem(`cosmos-avatar-state-${state.accountId}`, JSON.stringify(state.avatarState)); queueServerSync(); }
function saveActiveAccount() { localStorage.setItem('cosmos-active-account', state.accountId); }
let serverSyncTimer = null;
function persistedSnapshot() { return { records: state.records, assistantMessages: state.assistantMessages.slice(-24), questObjectiveId: state.questObjectiveId, llmConsent: state.llmConsent, lastLlmAnalysis: state.lastLlmAnalysis, digitalId: state.digitalId, avatarState: state.avatarState }; }
function queueServerSync() { if (!state.remoteReady || serverSyncTimer) return; serverSyncTimer = setTimeout(async () => { serverSyncTimer = null; state.persistenceStatus = 'syncing'; try { const response = await fetch('/api/cosmos/state', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ accounts: state.accounts, activeAccountId: state.accountId, state: persistedSnapshot() }) }); if (!response.ok) throw new Error('sync failed'); state.persistenceStatus = 'synced'; } catch { state.persistenceStatus = 'local-fallback'; } }, 350); }
async function hydrateFromServer(accountId = state.accountId) { state.remoteReady = false; try { const response = await fetch(`/api/cosmos/state?accountId=${encodeURIComponent(accountId)}`); const payload = await response.json(); if (payload.persistent && Array.isArray(payload.accounts) && payload.accounts.length) { const localById = new Map(state.accounts.map(account => [account.id, account])); payload.accounts.forEach(account => localById.set(account.id, { ...localById.get(account.id), ...account })); state.accounts = Array.from(localById.values()); } if (payload.state && accountId === state.accountId) { const remote = payload.state; state.records = Array.isArray(remote.records) ? normalizeRecords(remote.records) : state.records; state.assistantMessages = Array.isArray(remote.assistantMessages) ? remote.assistantMessages : state.assistantMessages; state.questObjectiveId = objectives.some(item => item.id === remote.questObjectiveId) ? remote.questObjectiveId : state.questObjectiveId; state.llmConsent = Boolean(remote.llmConsent); state.lastLlmAnalysis = remote.lastLlmAnalysis || null; state.digitalId = remote.digitalId || state.digitalId; state.avatarState = remote.avatarState || state.avatarState; } state.persistenceStatus = payload.persistent ? 'synced' : 'local-fallback'; } catch { state.persistenceStatus = 'local-fallback'; } finally { state.remoteReady = true; queueServerSync(); render(); } }
function gradeBand(record) { if (!hasCompleteRubric(record.scores)) return 'In progress'; const score = avg(record.scores || []); if (record.status === 'Mastered' && score >= 3.5) return 'A'; if (score >= 3) return 'B'; if (score >= 2) return 'C'; return 'In progress'; }
function gradeLabel(record) { const ratings = assessedRatings(record.scores); if (!ratings.length) return 'Not assessed'; const score = avg(ratings); return `${gradeBand(record)} · ${score.toFixed(1)}/4${hasCompleteRubric(record.scores) ? ' rubric average' : ' assessed only · incomplete rubric'}`; }
function questStage(record) { if (!record) return { name: 'Observe', copy: 'Read the objective and name what you notice.', action: 'Open the knowledge check' }; if (record.status === 'Mastered') return { name: 'Contribute', copy: 'Transfer the idea to a new audience or context.', action: 'Create an extension' }; if (record.status === 'Revision needed') return { name: 'Experiment', copy: 'Revise one weak signal and test the change.', action: 'Return to the proof workspace' }; if (record.status === 'Reviewed') return { name: 'Connect', copy: 'Link the reviewed idea to another context.', action: 'Choose a connection' }; return { name: 'Understand', copy: 'Make the concept visible in your own words.', action: 'Build evidence' }; }
function currentQuest() { return objectives.find(item => item.id === state.questObjectiveId) || objectives[0]; }
function nextLumaAvatarState(event) { const current = state.avatarState || loadAvatarState(); const type = event.type; let mode = current.mode; let message = lumaAvatarModes[mode]?.cue || lumaAvatarModes.idle.cue; if (type === 'OBJECTIVE_SELECTED') { mode = 'explaining'; message = `Framing ${event.objectiveId} as an observable learning move.`; } else if (type === 'KNOWLEDGE_CHECK_STARTED') { mode = 'thinking'; message = 'Take a moment to connect the idea in your own words.'; } else if (type === 'KNOWLEDGE_CHECK_COMPLETED') { mode = event.correct ? 'encouraging' : 'revision'; message = event.correct ? 'Your model is aligned with the core idea. Now make the evidence visible.' : 'A revision is useful here. Find one claim you can test or explain more clearly.'; } else if (type === 'PROOF_SUBMITTED') { mode = 'reviewing'; message = 'Your evidence is queued for human educator review.'; } else if (type === 'FORMATIVE_SIGNAL_READY') { mode = 'encouraging'; message = 'A formative signal is ready: strengths, gaps, and a next practice move.'; } else if (type === 'HUMAN_REVIEW_RECORDED') { mode = event.status === 'Revision needed' ? 'revision' : event.status === 'Mastered' ? 'celebrating' : 'encouraging'; message = event.status === 'Mastered' ? 'A human review was recorded. Carry the idea into a new context.' : `Human review recorded as ${event.status}. Choose one next revision.`; } else if (type === 'ASSISTANT_MESSAGE') { mode = 'explaining'; message = 'Turning your question into a curriculum-linked next step.'; } else if (type === 'SESSION_READY') { mode = 'idle'; }
  return { mode, objectiveId: event.objectiveId || current.objectiveId || state.questObjectiveId, lastEvent: type, message, updatedAt: formatDate() };
}
function dispatchLearningEvent(event) { state.avatarState = nextLumaAvatarState(event); saveAvatarState(); if (state.route === 'assistant') render(); }
function curriculumGuideVisual(quest, stage) { return `<div class="curriculum-guide-strip"><div class="curriculum-guide-avatar avatar-mode-${state.avatarState?.mode || 'idle'}"><video class="curriculum-guide-video" autoplay muted loop playsinline poster="/assets/avatar/luma-avatar-vector.svg" aria-label="Animated COSMOS curriculum guide visual"><source src="/assets/avatar/luma-guide-cutout.webm" type="video/webm" /></video><img class="curriculum-guide-vector" src="/assets/avatar/luma-avatar-vector.svg" alt="Vectorized COSMOS curriculum guide silhouette" /></div><div><div class="panel-kicker">LUMA / CURRICULUM GUIDE · ${esc((lumaAvatarModes[state.avatarState?.mode] || lumaAvatarModes.idle).label)}</div><strong>${esc(stage.name)} · ${esc(quest.domain)}</strong><p>Visual cue synced to <em>${esc(quest.title)}</em>.</p><span class="avatar-cue">${esc(state.avatarState?.message || lumaAvatarModes.idle.cue)}</span><small>Reference-derived visual · use only with appropriate consent for public identity representation.</small></div></div>`; }
function assistantQuestPanel() { const quest = currentQuest(); const record = state.records.find(item => item.objectiveId === quest.id); const stage = questStage(record); return `<section class="panel assistant-quest">${curriculumGuideVisual(quest, stage)}<div class="panel-header"><div><div class="panel-kicker">CURRICULUM QUEST LOG</div><h2 class="panel-title">${esc(quest.id)} · ${esc(quest.domain)}</h2><p class="panel-copy">${esc(quest.title)}</p></div><span class="badge ${record ? statusClass(record.status) : 'badge-amber'}">${record ? esc(record.status.toUpperCase()) : 'NOT STARTED'}</span></div><div class="field"><label class="form-label" for="assistant-objective">Active curriculum objective</label><select id="assistant-objective" class="select" data-assistant-objective>${objectives.map(item => `<option value="${item.id}" ${item.id === quest.id ? 'selected' : ''}>${item.id} · ${item.title}</option>`).join('')}</select></div><div class="quest-stage"><div class="quest-stage-marker">${stage.name.slice(0, 2).toUpperCase()}</div><div><strong>${stage.name}</strong><p>${stage.copy}</p><span>${stage.action}</span></div></div><div class="quest-log-list">${objectives.map(item => { const itemRecord = state.records.find(entry => entry.objectiveId === item.id); const itemStage = questStage(itemRecord); return `<button class="quest-log-item ${item.id === quest.id ? 'active' : ''}" data-quest-id="${item.id}"><span class="quest-log-id">${item.id}</span><span><strong>${esc(item.title)}</strong><small>${itemStage.name} · ${itemRecord ? itemRecord.status : 'Not started'}</small></span></button>`; }).join('')}</div></section>`; }
function assistantLlmPanel() { const analysis = state.lastLlmAnalysis; return `<section class="panel pad assistant-llm"><div class="panel-header"><div><div class="panel-kicker">FORMATIVE AI SIGNAL</div><h2 class="panel-title">Expand the lesson</h2><p class="panel-copy">LUMA can examine the active quest response and suggest practice. It does not grade, diagnose ability, or replace an educator.</p></div><span class="badge ${state.llmConsent ? 'badge-green' : 'badge-muted'}">${state.llmConsent ? 'OPTED IN' : 'OFF'}</span></div><label class="consent-check"><input type="checkbox" data-llm-consent ${state.llmConsent ? 'checked' : ''}/><span><strong>Allow formative AI analysis</strong><small>Your objective, proof summary, and prompt text may be sent to COSMOS AI for this response. Do not include sensitive personal information. Voice and Digital ID images are never sent.</small></span></label><button class="btn btn-primary" data-action="run-formative-analysis" ${state.llmConsent && !state.llmPending ? '' : 'disabled'}>${state.llmPending ? 'LUMA is thinking…' : 'Analyze my active quest ' + icon('arrow')}</button>${analysis ? `<div class="llm-result"><div class="llm-result-head"><span class="badge badge-cyan">OBSERVED SIGNALS · ${esc(analysis.objectiveId || currentQuest().id)}</span><span class="small-mono">${esc(analysis.createdAt || 'local')}</span></div><p><strong>${esc(analysis.summary)}</strong></p><div class="llm-columns"><div><span class="panel-kicker">STRENGTHS</span><ul>${(analysis.strengths || []).map(item => `<li>${esc(item)}</li>`).join('')}</ul></div><div><span class="panel-kicker">GAPS TO EXPLORE</span><ul>${(analysis.gaps || []).map(item => `<li>${esc(item)}</li>`).join('')}</ul></div></div><div class="llm-next"><strong>Next practice</strong><p>${esc(analysis.nextStep)}</p><span>${esc(analysis.practiceQuestion)}</span></div><small class="helper">${esc(analysis.caution || 'This is formative guidance, not a grade or mastery decision.')}</small></div>` : '<div class="empty">Opt in, then ask LUMA to analyze your active curriculum quest after you have a proof response or saved record.</div>'}</section>`; }
function assistantResponse(prompt) { const text = prompt.toLowerCase(); const account = currentAccount(); const quest = currentQuest(); const latest = state.records.find(record => record.objectiveId === quest.id) || state.records[0]; const stage = questStage(latest); if (text.includes('curriculum') || text.includes('quest') || text.includes('objective')) return `Your active curriculum quest is ${quest.id}: ${quest.title}. You are in the ${stage.name} phase. ${stage.copy} ${stage.action} is the next useful move.`; if (text.includes('progress') || text.includes('report') || text.includes('grade')) return `Your account has ${state.records.length} saved proof record${state.records.length === 1 ? '' : 's'}. ${latest ? `For ${latest.objectiveId}, your latest record is ${latest.status.toLowerCase()} with a ${gradeBand(latest)} prototype band.` : `Your ${quest.id} quest has not started yet.`} Remember: a band is a transparent demo signal, not an accreditation.`; if (text.includes('photosynthesis') || text.includes('bio') || (quest.id === 'BIO-04' && text.includes('proof'))) return `For BIO-04, make the transformation visible: light energy enters the system, and chemical energy is stored in glucose. Add one source note or a small testable diagram, then check whether each arrow in your explanation has evidence.`; if (text.includes('source') || text.includes('reliable') || quest.id === 'RES-02' && text.includes('evidence')) return `For RES-02, compare the source’s origin, purpose, evidence, and uncertainty. State what would change your judgment instead of calling a source simply good or bad.`; if (text.includes('model') || text.includes('error') || quest.id === 'COM-07' && text.includes('test')) return `For COM-07, use a small test set to find where the model fails. Describe the pattern of error, then name one limit your test cannot establish.`; if (text.includes('next') || text.includes('stuck') || text.includes('help')) return `Start with one observable next step for ${quest.id}. ${latest ? `Revisit the dimensions below Proficient and write one sentence explaining what evidence would raise each signal.` : `Open the knowledge check, answer in your own words, and attach a short explanation.`}`; return `I’m here to help you turn ${quest.domain.toLowerCase()} thinking into evidence, ${account.name}. Ask about this quest, your progress, the evidence, or your next step.`; }
function objective() { return objectives.find(item => item.id === state.objectiveId) || objectives[0]; }
function esc(value = '') { return String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char])); }
function icon(name) { return ICONS[name] || ''; }
function routeTo(route) { state.route = route; state.proofStep = route === 'proof' ? state.proofStep : 1; location.hash = route; render(); window.scrollTo({ top: 0, behavior: 'smooth' }); }
function showToast(title, message) { state.toast = { title, message }; render(); setTimeout(() => { state.toast = null; render(); }, 3600); }
function statusClass(status) { if (status === 'Mastered') return 'badge-green'; if (status === 'Revision needed') return 'badge-red'; if (status === 'Reviewed') return 'badge-cyan'; return 'badge-amber'; }
function avg(scores) { const ratings = assessedRatings(scores); return ratings.length ? Math.round((ratings.reduce((a, b) => a + b, 0) / ratings.length) * 10) / 10 : 0; }
function masteryStatus(scores = state.scores, submitted = false, humanReviewed = false) { if (submitted && humanReviewed && hasCompleteRubric(scores) && scores.every(score => score >= 3)) return 'Mastered'; if (submitted && humanReviewed) return 'Reviewed'; if (submitted) return 'Submitted'; return 'In progress'; }
function formatDate() { return new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date()); }

function shell(content) {
  const profile = currentRole();
  const account = currentAccount();
  const navItems = state.role === 'educator'
    ? [['home', 'Overview', 'home'], ['educator', 'Review queue', 'educator'], ['reports', 'Report ledger', 'portfolio'], ['atlas', 'Learning Atlas', 'atlas'], ['pathways', 'Pathways', 'path']]
    : state.role === 'parent'
      ? [['home', 'Family overview', 'home'], ['reports', 'Shared reports', 'portfolio'], ['portfolio', 'Shared portfolio', 'portfolio'], ['pathways', 'Learning pathways', 'path'], ['atlas', 'Learning Atlas', 'atlas']]
      : [['home', 'Home', 'home'], ['proof', 'COSMOS PROOF', 'proof'], ['assistant', 'Orbital assistant', 'spark'], ['digital-id', 'Digital ID', 'spark'], ['reports', 'Saved reports', 'portfolio'], ['portfolio', 'Portfolio', 'portfolio'], ['atlas', 'Learning Atlas', 'atlas'], ['pathways', 'Pathways', 'path']];
  return `<div class="layout">
    <aside class="sidebar">
      <button class="brand" data-route="home" aria-label="Go to COSMOS ACADEMIA home"><span class="brand-mark"><span class="brand-core"></span></span><span><span class="brand-name">COSMOS</span><span class="brand-sub">ACADEMIA / LEARNING OBSERVATORY</span></span></button>
      <div class="role-switcher"><div class="role-switcher-head"><span class="nav-label" style="padding:0;margin:0">Prototype role</span><span class="badge badge-${profile.color}">${profile.badge}</span></div><label class="sr-only" for="role-switcher">Switch prototype role</label><select id="role-switcher" class="select role-select" data-role-switch>${Object.entries(roleProfiles).map(([key, item]) => `<option value="${key}" ${state.role === key ? 'selected' : ''}>${item.label} · ${item.description}</option>`).join('')}</select></div>
      <div class="account-switcher"><div class="role-switcher-head"><span class="nav-label" style="padding:0;margin:0">Local account</span><span class="small-mono">${state.accounts.length} SAVED</span></div><label class="sr-only" for="account-switcher">Switch local account</label><select id="account-switcher" class="select role-select" data-account-switch>${state.accounts.map(accountItem => `<option value="${accountItem.id}" ${accountItem.id === state.accountId ? 'selected' : ''}>${esc(accountItem.name)}${accountItem.demo ? ' · demo' : ''}</option>`).join('')}</select></div>
      <div class="nav-label">Workspace</div>
      <nav class="nav-group" aria-label="Primary navigation">${navItems.map(([route, label, ico]) => `<button class="nav-item ${state.route === route ? 'active' : ''}" data-route="${route}">${icon(ico)}<span>${label}</span></button>`).join('')}</nav>
      <div class="nav-label" style="margin-top:22px">System</div>
      <nav class="nav-group"><button class="nav-item ${state.route === 'settings' ? 'active' : ''}" data-route="settings">${icon('settings')}<span>Settings & privacy</span></button><button class="nav-item ${state.route === 'about' ? 'active' : ''}" data-route="about">${icon('about')}<span>About COSMOS</span></button></nav>
      <div class="sidebar-bottom"><div class="demo-card"><div class="demo-row"><span class="avatar" style="background:linear-gradient(135deg,var(--${profile.color}),var(--violet))">${profile.initials}</span><span><span class="demo-name">${esc(state.role === 'student' ? account.name : profile.name)}</span><span class="demo-role">${profile.label} view · ${account.demo ? 'local demo' : 'local account'}</span></span></div><p class="demo-note">${profile.description} Progress syncs to the managed database when available, with a browser-local fallback.</p></div></div>
    </aside>
    <main class="main"><header class="topbar"><div class="breadcrumb"><span>COSMOS ACADEMIA</span><span class="slash">/</span><strong>${pageLabel(state.route)}</strong></div><div class="top-actions"><div class="status-chip"><span class="status-dot"></span>${profile.badge} · LOCAL DEMO</div><button class="icon-btn" aria-label="Search" data-action="search">${icon('search')}</button>${state.role === 'student' ? `<button class="icon-btn" aria-label="Open proof workspace" data-route="proof">${icon('proof')}</button>` : ''}</div></header>${content}</main></div>${state.toast ? `<div class="toast"><strong>${esc(state.toast.title)}</strong>${esc(state.toast.message)}</div>` : ''}`;
}
  function pageLabel(route) { return ({ home: 'Home', proof: 'COSMOS PROOF', assistant: 'Orbital assistant', 'digital-id': 'Digital ID', reports: 'Saved reports & grades', portfolio: 'Portfolio', atlas: 'Learning Atlas', pathways: 'Pathways', educator: 'Educator view', settings: 'Settings & privacy', about: 'About COSMOS' })[route] || 'Home'; }
function pageTitle(eyebrow, title, intro, action = '') { return `<div class="page-heading-row"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1>${intro ? `<p class="page-intro">${intro}</p>` : ''}</div>${action}</div>`; }
function actionButton(label, route = '', className = 'btn btn-primary', action = '') { return `<button class="${className}" ${route ? `data-route="${route}"` : ''} ${action ? `data-action="${action}"` : ''}>${label}</button>`; }
function statCard(label, value, meta, color = 'cyan') { return `<div class="panel stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon" style="color:var(--${color})">${icon('spark')}</span></div><div class="stat-value">${value}</div><div class="stat-meta">${meta}</div></div>`; }

function roleBoundary(title, copy, route = 'home', action = 'Return to my view') { return `<div class="page">${pageTitle('Role boundary', title, copy, `<button class="btn btn-primary" data-route="${route}">${action} ${icon('arrow')}</button>`)}<section class="panel pad"><div class="notice"><strong>Prototype privacy rule.</strong> Role switching changes the demo lens, not the underlying identity. Student drafts and private notes are not exposed in the Parent view, and educator actions remain reserved for the Educator view.</div></section></div>`; }

function analyticsBar(label, value, max = 100, color = 'cyan', meta = '') { return `<div class="analytics-bar-row"><div class="analytics-bar-label"><span>${esc(label)}</span><strong>${value}${max === 100 ? '%' : ''}</strong></div><div class="analytics-bar-track"><span class="analytics-bar-fill" style="width:${Math.min(100, value / max * 100)}%;background:linear-gradient(90deg,var(--${color}),var(--violet))"></span></div>${meta ? `<small>${esc(meta)}</small>` : ''}</div>`; }
function miniChart(values, color = 'cyan') { return `<div class="mini-chart" aria-label="Trend chart">${values.map((value, index) => `<span class="mini-bar" style="height:${value}%;background:linear-gradient(180deg,var(--${color}),rgba(169,156,255,.34));" title="Cycle ${index + 1}: ${value}"></span>`).join('')}</div><div class="chart-axis"><span>Earlier</span><span>Current cycle</span></div>`; }

function renderEducatorHome() {
  const pending = state.records.filter(record => !record.reviewed).length;
  const rubricSignals = [['Conceptual understanding', 82, 'cyan'], ['Reasoning', 68, 'violet'], ['Application', 55, 'amber'], ['Verification / source quality', 44, 'green']];
  const reviewTarget = state.records.find(record => record.status !== 'Mastered');
  return shell(`<div class="page">${pageTitle('Educator analytics · role switch demo', 'See where to add <em>signal.</em>', 'A cohort-level view of evidence quality, review flow, and next-step opportunities. Demo analytics are for calibration, not ranking.', actionButton('Open review queue ' + icon('arrow'), 'educator'))}
    <div class="grid grid-4 section-space">${statCard('Active learners', '18', 'demo cohort · 4 pathways', 'violet')} ${statCard('Awaiting review', pending.toString().padStart(2, '0'), 'evidence needs a human', 'amber')} ${statCard('Evidence this cycle', '42', '+14 from last cycle')} ${statCard('Mastery-ready', '68%', 'relevant dimensions ≥ 3', 'green')}</div>
    <div class="grid grid-2 section-space"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Cohort mastery distribution</h2><p class="panel-copy">Signals across reviewed evidence, shown as a calibration view.</p></div><span class="badge badge-amber">DEMO COHORT</span></div><div class="analytics-legend"><span><i class="legend-dot dot-cyan"></i>Evidence signal</span><span><i class="legend-dot dot-violet"></i>Human-reviewed</span></div><div class="analytics-bars">${analyticsBar('Emerging', 6, 42, 'amber', 'needs an observable next step')}${analyticsBar('Developing', 11, 42, 'violet', 'partial evidence across dimensions')}${analyticsBar('Proficient', 18, 42, 'cyan', 'relevant dimensions are consistent')}${analyticsBar('Advanced', 7, 42, 'green', 'transfer and verification are visible')}</div></section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Review throughput</h2><p class="panel-copy">A lightweight trend of completed human reviews.</p></div><span class="small-mono">LAST 6 CYCLES</span></div>${miniChart([28, 42, 35, 56, 64, 78], 'cyan')}<div class="kpi-row"><div><strong>78%</strong><span>review completion</span></div><div><strong>2.4d</strong><span>median feedback loop</span></div><div><strong>94%</strong><span>audit coverage</span></div></div></section></div>
    <div class="grid grid-2 section-space"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Rubric signal map</h2><p class="panel-copy">Where educator calibration can improve the quality of evidence.</p></div><button class="panel-link" data-route="educator">Calibrate ratings</button></div><div class="analytics-bars">${rubricSignals.map(([label, value, color]) => analyticsBar(label, value, 100, color, value < 60 ? 'priority for feedback' : 'healthy signal')).join('')}</div><div class="notice" style="margin-top:17px"><strong>Interpretation:</strong> lower signals point to a feedback opportunity, not a learner deficit. Attendance and time-on-task are intentionally excluded.</div></section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Pathway coverage</h2><p class="panel-copy">Evidence activity by learning route, not by age or seat time.</p></div><span class="badge badge-cyan">4 PATHWAYS</span></div><div class="analytics-table"><div class="analytics-table-row analytics-table-head"><span>Pathway</span><span>Evidence</span><span>Reviewed</span></div>${[['Natural Sciences','16','81%'],['Research Methods','11','73%'],['Computing & AI','09','67%'],['Engineering & Design','06','58%']].map(([pathway,evidence,reviewed]) => `<div class="analytics-table-row"><strong>${pathway}</strong><span>${evidence} items</span><span class="kpi-accent">${reviewed}</span></div>`).join('')}</div></section></div>
    <section class="panel pad section-space"><div class="panel-header"><div><h2 class="panel-title">Next educator action</h2><p class="panel-copy">Turn the analytics into one concrete review move.</p></div><span class="badge badge-amber">ACTIONABLE</span></div>${reviewTarget ? `<div class="signal-callout"><div class="side-list-icon">${reviewTarget.id.slice(-2)}</div><div><strong>${esc(reviewTarget.title)}</strong><p>${esc(reviewTarget.feedback)}</p></div><button class="btn btn-primary" data-route="educator">Open review ${icon('arrow')}</button></div>` : '<div class="empty">The demo review queue is clear.</div>'}</section>
  </div>`);
}

function renderParentHome() {
  const progressSignals = [['Conceptual understanding', 82, 'cyan'], ['Reasoning', 68, 'violet'], ['Application', 55, 'amber'], ['Verification', 44, 'green']];
  return shell(`<div class="page">${pageTitle('Parent progress · consented lens', 'Follow the <em>learning arc.</em>', 'A family-facing progress dashboard built from learner-approved evidence. It intentionally avoids surveillance metrics and private process data.', actionButton('View shared portfolio ' + icon('arrow'), 'portfolio'))}
    <section class="panel hero-panel"><div class="hero-copy"><div><div class="hero-kicker">Shared by consent · Demo Learner</div><h2 class="hero-title">Progress is a trail of <span>better questions.</span></h2><p class="hero-text">The learner is moving from noticing a living system to explaining, testing, and revising an idea about photosynthesis.</p></div><div class="hero-actions"><button class="btn btn-primary" data-route="portfolio">Open shared evidence ${icon('arrow')}</button><button class="btn btn-ghost" data-route="pathways">See the pathway</button></div></div><div class="orbit-scene" aria-label="Consent and progress diagram"><span class="hero-index">FAMILY LENS / CONSENTED</span><span class="orbit-node node-a"></span><span class="orbit-node node-b"></span><span class="orbit-node node-c"></span><span class="orbit-node node-d"></span><span class="orbit-core"></span></div></section>
    <div class="grid grid-4 section-space">${statCard('Shared evidence', '02', 'learner-approved items')} ${statCard('Learning arc', '03/04', 'milestones visible', 'violet')} ${statCard('Current signal', '74%', 'rubric evidence only', 'amber')} ${statCard('Privacy state', state.shareConsent ? 'ON' : 'LOCAL', state.shareConsent ? 'consent recorded' : 'demo-only preview', 'green')}</div>
    <div class="grid grid-2 section-space"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Learning arc</h2><p class="panel-copy">A sequence of observable milestones, not a grade ladder.</p></div><span class="badge badge-green">CONSENTED</span></div><div class="milestone-track">${[['Observe','Patterns noticed','done'],['Understand','Energy transformation explained','done'],['Experiment','Testable diagram requested','current'],['Contribute','Share a verified explanation','next']].map(([title,copy,status], index) => `<div class="milestone ${status}"><span class="milestone-node">${status === 'done' ? '✓' : `0${index + 1}`}</span><div><strong>${title}</strong><p>${copy}</p></div></div>`).join('')}</div></section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Shared competency signals</h2><p class="panel-copy">These are evidence snapshots, not a measure of effort or attendance.</p></div><span class="small-mono">4 DIMENSIONS</span></div><div class="analytics-bars">${progressSignals.map(([label, value, color]) => analyticsBar(label, value, 100, color)).join('')}</div></section></div>
    <div class="grid grid-2 section-space"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Evidence trajectory</h2><p class="panel-copy">The quality of the shared record across recent learner-approved items.</p></div><span class="small-mono">LOCAL DEMO</span></div>${miniChart([38, 46, 52, 61, 68, 74], 'violet')}<div class="kpi-row"><div><strong>02</strong><span>shared items</span></div><div><strong>03</strong><span>dimensions rising</span></div><div><strong>01</strong><span>next conversation</span></div></div></section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Support without surveillance</h2><p class="panel-copy">Use the dashboard to ask better questions.</p></div></div><div class="callout"><strong>Not tracked:</strong> attendance, time-on-task, private drafts, raw feedback notes, file contents, or sensitive child data. Progress is based only on learner-approved evidence.</div><div class="form-actions"><span class="helper">Consent can be withdrawn from the shared portfolio.</span><button class="btn btn-ghost" data-route="portfolio">Manage consent ${icon('arrow')}</button></div></section></div>
  </div>`);
}

function renderHome() {
  if (state.role === 'educator') return renderEducatorHome();
  if (state.role === 'parent') return renderParentHome();
  const records = state.records;
  return shell(`<div class="page">${pageTitle('Learner dashboard · 01', 'Make the learning <em>visible.</em>', 'A calm place to continue, test, explain, and carry evidence forward. Your workspace is private by default.', '<button class="btn btn-primary" data-route="proof">Open COSMOS PROOF ' + icon('arrow') + '</button>')}
    <section class="panel hero-panel"><div class="hero-copy"><div><div class="hero-kicker">Signal received · Wednesday, 01 Nov 2026</div><h2 class="hero-title">Good to see you, <span>${esc(currentAccount().name)}.</span></h2><p class="hero-text">Your next proof task is ready: show how a living system turns light into stored chemical energy. One small explanation can become durable evidence.</p></div><div class="hero-actions"><button class="btn btn-primary" data-route="proof">Continue proof task ${icon('arrow')}</button><button class="btn btn-ghost" data-route="portfolio">View portfolio</button></div></div><div class="orbit-scene" aria-label="Orbital knowledge diagram"><span class="hero-index">FIELD 04 / 09</span><span class="orbit-node node-a"></span><span class="orbit-node node-b"></span><span class="orbit-node node-c"></span><span class="orbit-node node-d"></span><span class="orbit-core"></span></div></section>
    <div class="grid grid-4 section-space">${statCard('Proofs completed', '06', '+2 this cycle')} ${statCard('Competencies active', '12', 'across 4 pathways', 'violet')} ${statCard('Evidence items', '18', '2 need revision', 'amber')} ${statCard('Mastery signal', '74%', 'human-reviewed only', 'green')}</div>
    <div class="grid grid-2 section-space"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Continue learning</h2><p class="panel-copy">A short route into the next observable action.</p></div><span class="badge badge-cyan">IN PROGRESS</span></div><div class="side-list"><div class="side-list-item"><div class="side-list-icon">01</div><div class="side-list-copy"><div class="side-list-title"><strong>${esc(objective().title)}</strong></div><div class="side-list-meta">Natural Sciences · explanation + diagram</div></div></div></div><div style="margin-top:20px"><div class="progress-meta"><span>Evidence assembled</span><strong>2 of 4 signals</strong></div><div class="progress-line"><span style="width:52%"></span></div></div><div class="form-actions"><span class="helper">Next: add one source note, then submit for educator review.</span><button class="btn btn-ghost" data-route="proof">Resume ${icon('arrow')}</button></div></section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Proof tasks due</h2><p class="panel-copy">Prioritized by pathway, not by time-on-task.</p></div><button class="panel-link" data-route="pathways">All pathways</button></div><div class="side-list">${objectives.map(item => `<button class="side-list-item" style="text-align:left;background:none;border:0;color:inherit;padding:0" data-objective="${item.id}" data-route="proof"><div class="side-list-icon" style="color:var(--${item.accent})">${item.id.slice(0,2)}</div><div class="side-list-copy"><div class="side-list-title">${esc(item.title)}</div><div class="side-list-meta">${item.domain} · ${item.due}</div></div></button>`).join('')}</div></section></div>
    <div class="grid grid-2 section-space"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Progress by competency</h2><p class="panel-copy">A snapshot of evidence quality across your current pathway.</p></div><button class="panel-link" data-route="portfolio">Details</button></div>${[['Conceptual understanding', 82], ['Reasoning', 68], ['Application', 55], ['Verification / source quality', 44]].map(([label, value]) => `<div class="competency-item"><div class="progress-meta"><span>${label}</span><strong>${value}%</strong></div><div class="progress-line"><span style="width:${value}%"></span></div></div>`).join('')}</section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Recent evidence</h2><p class="panel-copy">The record stays useful when the next step is clear.</p></div><button class="panel-link" data-route="portfolio">Open portfolio</button></div><div class="side-list">${records.slice(0, 3).map(record => `<div class="side-list-item"><div class="side-list-icon">${record.id.slice(-2)}</div><div class="side-list-copy"><div class="side-list-title">${esc(record.title)}</div><div class="side-list-meta">${record.type} · <span class="badge ${statusClass(record.status)}">${record.status}</span></div></div></div>`).join('')}</div></section></div>
  </div>`);
}

function proofStepper() { return `<div class="stepper">${[['01','Check'],['02','Evidence'],['03','Review']].map(([num, label], index) => `<div class="step ${state.proofStep === index + 1 ? 'current' : state.proofStep > index + 1 ? 'done' : ''}"><b>${state.proofStep > index + 1 ? '✓' : num}</b><span>${label}</span></div>${index < 2 ? '<div class="step-line"></div>' : ''}`).join('')}</div>`; }
function renderProof() {
  if (state.role !== 'student') return shell(roleBoundary(state.role === 'parent' ? 'The proof draft belongs to the learner.' : 'Proof review belongs to the educator.', state.role === 'parent' ? 'Parent view shows only learner-approved progress summaries. Switch to Student to work on a proof task.' : 'Educator view is the place to review submitted evidence. Switch to Student to create a new proof attempt.', state.role === 'parent' ? 'portfolio' : 'educator', state.role === 'parent' ? 'View shared portfolio' : 'Open educator review'));
  const obj = objective();
  const latest = state.records.find(record => record.objectiveId === obj.id);
  return shell(`<div class="page">${pageTitle('COSMOS PROOF · primary workspace', 'Turn a question into <em>evidence.</em>', 'Choose an objective, make your thinking observable, then let a human review the record. This is a demo workspace; it is not accreditation.', '<span class="badge badge-amber">DEMO DATA · LOCAL ONLY</span>')}
    <div class="proof-layout"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Proof record</h2><p class="panel-copy">A structured attempt that can be revised, reviewed, and carried into your portfolio.</p></div><span class="small-mono">RECORD ${latest?.id || 'NEW-105'}</span></div>${proofStepper()}<div class="field"><label class="form-label" for="objective-select">Learning objective</label><select id="objective-select" class="select" data-change="objective">${objectives.map(item => `<option value="${item.id}" ${item.id === obj.id ? 'selected' : ''}>${item.id} · ${item.title}</option>`).join('')}</select></div>${state.proofStep === 1 ? proofCheckStep(obj) : state.proofStep === 2 ? proofEvidenceStep(obj) : proofReviewStep(obj)}</section><aside class="aside-stack">${proofSidePanel(obj, latest)}</aside></div>
  </div>`);
}
function proofCheckStep(obj) {
  const result = state.checkResult ? `<div class="callout" style="margin-top:15px"><strong>${state.checkResult.correct ? 'Good signal.' : 'Useful revision signal.'}</strong> ${state.checkResult.message}</div>` : '';
  return `<div style="margin-top:23px"><div class="notice"><strong>Knowledge check</strong> — Answer in your own words first. This check is a signal for reflection, not the sole basis for mastery.</div><div style="margin-top:17px"><div class="check-item"><p class="check-q">1. Which statement best describes the main transformation in photosynthesis?</p>${[['a','Light energy is destroyed as heat.'],['b','Light energy is stored in chemical bonds such as glucose.'],['c','Carbon dioxide becomes light energy.']].map(([value, label]) => `<label class="radio-option"><input type="radio" name="q1" value="${value}" ${state.proofAnswers.q1 === value ? 'checked' : ''} data-answer="q1" />${label}</label>`).join('')}</div><div class="check-item"><p class="check-q">2. What evidence would make your explanation more trustworthy?</p>${[['a','A longer timer.'],['b','A source note and a testable diagram.'],['c','A claim that sounds confident.']].map(([value, label]) => `<label class="radio-option"><input type="radio" name="q2" value="${value}" ${state.proofAnswers.q2 === value ? 'checked' : ''} data-answer="q2" />${label}</label>`).join('')}</div></div>${result}<div class="form-actions"><span class="helper">Two questions · retakes are always allowed.</span><div class="form-actions-right"><button class="btn btn-primary" data-proof-next="2">Continue to evidence ${icon('arrow')}</button></div></div></div>`;
}
function proofEvidenceStep(obj) {
  return `<div style="margin-top:23px"><div class="notice"><strong>Practical evidence task</strong> — Create a labeled sketch, short explanation, or small experiment that shows where light energy goes. Add enough context for another person to understand your choices.</div><div style="margin-top:17px"><div class="form-row"><div class="field"><label class="form-label" for="submission-type">Submission type</label><select id="submission-type" class="select" data-proof-field="type">${['Explanation','Experiment','Project','Presentation','Code / artifact'].map(type => `<option ${state.proofEvidence.type === type ? 'selected' : ''}>${type}</option>`).join('')}</select></div><div class="field"><label class="form-label" for="proof-file">Attach evidence file</label><input id="proof-file" class="input" type="file" data-proof-file accept=".pdf,.png,.jpg,.jpeg,.txt,.md" /></div></div><div class="field"><label class="form-label" for="evidence-description">Evidence description</label><textarea id="evidence-description" class="textarea" data-proof-field="description" placeholder="What did you make or do? What does it show? What would another person be able to verify?">${esc(state.proofEvidence.description)}</textarea><div class="helper" style="margin-top:7px">${state.proofEvidence.file ? `Attached locally: ${esc(state.proofEvidence.file)} · ` : ''}No file leaves this browser in the MVP.</div></div></div><div class="form-actions"><button class="btn btn-ghost" data-proof-next="1">Back</button><div class="form-actions-right"><button class="btn btn-primary" data-proof-next="3">Continue to rubric ${icon('arrow')}</button></div></div></div>`;
}
function proofReviewStep(obj) {
  return `<div style="margin-top:23px"><div class="panel-header" style="margin-bottom:14px"><div><h3 class="panel-title">Assessment rubric</h3><p class="panel-copy">Score what the evidence makes observable. Choose the level that is defensible today.</p></div><span class="badge ${masteryStatus(state.scores, false) === 'Mastered' ? 'badge-green' : 'badge-amber'}">${masteryStatus(state.scores, false)}</span></div>${rubricGrid()}<div class="form-actions"><button class="btn btn-ghost" data-proof-next="2">Back</button><div class="form-actions-right"><button class="btn btn-primary" data-action="submit-proof">Submit for human review ${icon('arrow')}</button></div></div></div>`;
}
function rubricGrid() {
  return `<div class="rubric-grid"><div class="rubric-row"><div></div>${levels.map(level => `<div class="score-head">${level}</div>`).join('')}</div>${dimensions.map(([name, help], index) => `<div class="rubric-row"><div class="rubric-dimension">${name}<small>${help}</small></div>${levels.map((level, levelIndex) => `<button class="score-btn ${state.scores[index] === levelIndex + 1 ? 'selected' : ''}" data-score-index="${index}" data-score="${levelIndex + 1}" aria-label="${name}: ${level}">${levelIndex + 1}</button>`).join('')}</div>`).join('')}</div><div class="rubric-explain"><strong>What the levels mean:</strong> Emerging = a first signal is visible. Developing = the idea is taking shape with gaps. Proficient = the evidence is accurate and usable. Advanced = the learner transfers, tests, or extends the idea with unusual clarity. Time-on-task and attendance are never rubric dimensions.</div>`;
}
function proofSidePanel(obj, latest) {
  const status = latest?.status || 'In progress';
  return `<section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Objective signal</h2><p class="panel-copy">${obj.domain}</p></div><span class="badge ${statusClass(status)}">${status}</span></div><div class="callout"><strong>Mastery rule.</strong> Relevant dimensions must be Proficient or Advanced, evidence must be submitted, and an educator must explicitly review the record.</div><div style="margin-top:18px"><div class="progress-meta"><span>Current rubric average</span><strong>${avg(state.scores).toFixed(1)} / 4</strong></div><div class="progress-line"><span style="width:${avg(state.scores) / 4 * 100}%"></span></div></div></section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Attempt history</h2><p class="panel-copy">Revision is part of learning, not a failure state.</p></div><span class="panel-link">${state.records.filter(r => r.objectiveId === obj.id).length + 1} attempts</span></div>${latest ? `<div class="side-list-item"><div class="side-list-icon">${latest.id.slice(-2)}</div><div class="side-list-copy"><div class="side-list-title">${esc(latest.title)}</div><div class="side-list-meta">${latest.date} · <span class="badge ${statusClass(latest.status)}">${latest.status}</span></div></div></div>` : '<div class="empty">No submitted attempt yet. Your draft will appear here after review.</div>'}</section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Next steps</h2><p class="panel-copy">Keep the feedback actionable.</p></div></div><div class="side-list"><div class="side-list-item"><div class="side-list-icon">→</div><div class="side-list-copy"><div class="side-list-title">Add one verifiable source note</div><div class="side-list-meta">Strengthens verification / source quality</div></div></div><div class="side-list-item"><div class="side-list-icon">→</div><div class="side-list-copy"><div class="side-list-title">Ask an educator to review</div><div class="side-list-meta">Human oversight is required for mastery</div></div></div></div></section>`;
}

function renderPortfolio() {
  if (state.role === 'parent') return renderParentPortfolio();
  return shell(`<div class="page">${pageTitle('Verified learning portfolio · 03', 'Evidence that can <em>travel.</em>', 'A private record of what you can explain, make, test, and revise. Every item is labeled with its review context.', actionButton(icon('download') + ' Export local record', '', 'btn btn-ghost', 'export'))}
    <div class="grid grid-4 section-space">${statCard('Evidence items', state.records.length, 'saved proof records')} ${statCard('Mastered', state.records.filter(r => r.status === 'Mastered').length, 'human-reviewed', 'green')} ${statCard('Competencies', '12', 'demonstrated or emerging', 'violet')} ${statCard('Share state', state.shareConsent ? 'ON' : 'OFF', state.shareConsent ? 'consent recorded' : 'private by default', 'amber')}</div>
    <section class="panel pad section-space"><div class="panel-header"><div><h2 class="panel-title">Evidence ledger</h2><p class="panel-copy">Demo records are clearly marked. “Mastered” means this prototype’s explicit rule was met; it is not external accreditation.</p></div><span class="badge badge-amber">DEMO DATA INCLUDED</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Evidence item</th><th>Objective</th><th>Signals</th><th>Assessor</th><th>Status</th><th>Date</th></tr></thead><tbody>${state.records.map(record => `<tr><td><strong>${esc(record.title)}</strong><small>${record.type} · ${record.demo ? 'Demo learner' : 'Local draft'}</small></td><td><strong>${esc(record.objectiveId)}</strong><small>${esc((objectives.find(o => o.id === record.objectiveId) || {}).domain || 'Learning objective')}</small></td><td><strong>${assessedRatings(record.scores).length ? `${record.scores.filter(s => s >= 3).length}/8` : 'Not assessed'}</strong><small>dimensions ≥ Proficient</small></td><td><strong>${esc(record.assessor.split(' · ')[0])}</strong><small>${record.assessor.split(' · ')[1] || 'self-recorded'}</small></td><td><span class="badge ${statusClass(record.status)}">${record.status}</span></td><td>${record.date}</td></tr>`).join('')}</tbody></table></div></section>
    <div class="grid grid-2 section-space"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Share preview</h2><p class="panel-copy">Nothing is shared until you give explicit consent.</p></div><span class="badge ${state.shareConsent ? 'badge-green' : 'badge-muted'}">${state.shareConsent ? 'CONSENT ON' : 'PRIVATE'}</span></div><div class="notice">This preview would show selected evidence, competency signals, and assessor notes. It would never include sensitive child data or a public profile in this MVP.</div><label class="setting-row" style="margin-top:14px;padding:12px 0;background:transparent;border:0"><span class="setting-copy"><strong>Allow share preview</strong><p>Consent is local and can be withdrawn anytime.</p></span><span class="switch"><input type="checkbox" data-setting="shareConsent" ${state.shareConsent ? 'checked' : ''}/><span class="switch-track"></span></span></label></section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Assessment history</h2><p class="panel-copy">See the human decisions behind the status.</p></div></div><div class="audit">${state.records.slice(0, 3).map(record => `<div class="audit-item"><strong>${esc(record.title)}</strong> · ${record.status}<span class="audit-time">${esc(record.audit.at(-1) || 'No audit events recorded.')}</span></div>`).join('')}</div></section></div>
  </div>`);
}

function renderParentPortfolio() {
  return shell(`<div class="page">${pageTitle('Shared portfolio · parent view', 'See the signal, <em>protect the process.</em>', 'Only learner-approved evidence summaries appear here. Private drafts, raw feedback, and file contents remain hidden.', '<span class="badge badge-green">CONSENTED ITEMS ONLY</span>')}
    <section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Learner-approved evidence</h2><p class="panel-copy">Shared records are a starting point for conversation, not a report card.</p></div><span class="badge badge-cyan">DEMO LEARNER</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Shared item</th><th>Competency signal</th><th>Review state</th><th>What to ask</th></tr></thead><tbody>${state.records.map(record => `<tr><td><strong>${esc(record.title)}</strong><small>${record.type} · ${record.date}</small></td><td><strong>${assessedRatings(record.scores).length ? `${record.scores.filter(score => score >= 3).length}/8` : 'Not assessed'}</strong><small>rubric dimensions at Proficient+</small></td><td><span class="badge ${statusClass(record.status)}">${record.status}</span></td><td>${record.status === 'Mastered' ? 'What helped you compare the sources?' : 'What would you test or revise next?'}</td></tr>`).join('')}</tbody></table></div></section>
    <div class="grid grid-2 section-space"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Consent controls</h2><p class="panel-copy">The learner can withdraw sharing at any time.</p></div><span class="badge ${state.shareConsent ? 'badge-green' : 'badge-muted'}">${state.shareConsent ? 'ON' : 'OFF'}</span></div><div class="notice"><strong>Privacy by default.</strong> This prototype does not expose private drafts, notes, attendance, time-on-task, sensitive child data, or a public family profile.</div><label class="setting-row" style="margin-top:14px;padding:12px 0;background:transparent;border:0"><span class="setting-copy"><strong>Allow shared portfolio preview</strong><p>Local consent only; no data leaves this browser.</p></span><span class="switch"><input type="checkbox" data-setting="shareConsent" ${state.shareConsent ? 'checked' : ''}/><span class="switch-track"></span></span></label></section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Supportive conversation</h2><p class="panel-copy">Keep the learner in the driver’s seat.</p></div></div><div class="side-list">${['What changed in your thinking?','What evidence would make this clearer?','What support would make the next attempt easier?'].map((item, index) => `<div class="side-list-item"><div class="side-list-icon">0${index + 1}</div><div class="side-list-copy"><div class="side-list-title">${item}</div><div class="side-list-meta">Conversation prompt</div></div></div>`).join('')}</div></section></div>
  </div>`);
}

function renderReports() {
  const account = currentAccount();
  const records = visibleRecords();
  const assessedRecords = records.filter(record => assessedRatings(record.scores).length);
  const average = assessedRecords.length ? (assessedRecords.reduce((sum, record) => sum + avg(record.scores), 0) / assessedRecords.length).toFixed(1) : '—';
  const mastered = records.filter(record => record.status === 'Mastered').length;
  const title = state.role === 'parent' ? 'Shared reports' : state.role === 'educator' ? 'Report ledger' : 'Saved reports & grades';
  const intro = state.role === 'parent' ? 'Learner-approved report summaries for supportive conversations. Private drafts and raw notes remain hidden.' : 'Every saved report keeps the evidence, rubric dimensions, human review context, and prototype grade band together.';
  return shell(`<div class="page">${pageTitle(`${state.role === 'parent' ? 'Parent' : state.role === 'educator' ? 'Educator' : 'Student'} reports · local account`, 'Keep the <em>record.</em>', intro, actionButton(icon('download') + ' Export reports', '', 'btn btn-ghost', 'export-reports'))}
    <div class="grid grid-4 section-space">${statCard('Saved reports', String(records.length).padStart(2, '0'), state.role === 'parent' ? 'learner-approved items' : `in ${account.name}'s account`)} ${statCard('Rubric average', average, 'out of 4 · prototype signal', 'violet')} ${statCard('Mastered', String(mastered).padStart(2, '0'), 'explicit educator review', 'green')} ${statCard('Account state', account.demo ? 'DEMO' : 'LOCAL', 'browser-only persistence', 'amber')}</div>
    <section class="panel pad section-space"><div class="panel-header"><div><h2 class="panel-title">${title}</h2><p class="panel-copy">Reports are saved when a proof attempt is submitted. “Grades” are transparent prototype bands derived from rubric averages; they are not external accreditation.</p></div><span class="badge badge-cyan">${esc(account.name.toUpperCase())}</span></div>${records.length ? `<div class="report-list">${records.map(record => `<article class="report-card"><div class="report-card-top"><div><div class="panel-kicker">${esc(record.id)} · ${esc(record.date)}</div><h3>${esc(record.title)}</h3><p>${esc(record.objectiveId)} · ${esc(record.type)}</p></div><div class="report-grade"><strong>${gradeBand(record)}</strong><span>${gradeLabel(record)}</span></div></div><div class="report-card-meta"><span class="badge ${statusClass(record.status)}">${esc(record.status)}</span><span>${record.reviewed ? 'Human reviewed' : 'Awaiting human review'}</span><span>${esc(record.assessor || 'Self-recorded')}</span></div><div class="report-score-grid">${dimensions.slice(0, 4).map(([label], index) => `<div><span>${esc(label)}</span><strong>${record.scores[index] ?? '—'}/4</strong></div>`).join('')}</div><p class="report-feedback"><strong>Feedback:</strong> ${esc(record.feedback || 'No feedback recorded yet.')}</p></article>`).join('')}</div>` : `<div class="empty"><strong>No saved reports yet.</strong><br/>Submit a COSMOS PROOF attempt to create the first account-scoped report.</div>`}</section>
    <section class="panel pad section-space"><div class="panel-header"><div><h2 class="panel-title">How the prototype grade band works</h2><p class="panel-copy">The band is a reading aid for this demo, not a high-stakes judgment.</p></div><span class="badge badge-amber">TRANSPARENT RULE</span></div><div class="grade-legend"><div><strong>A</strong><span>Mastered with all relevant dimensions at Proficient+ and explicit human review.</span></div><div><strong>B</strong><span>Reviewed or mostly Proficient evidence with a clear next step.</span></div><div><strong>C</strong><span>Developing evidence that needs revision or another attempt.</span></div></div></section>
  </div>`);
}

function renderAssistant() {
  if (state.role !== 'student') return shell(roleBoundary('The Orbital Assistant is a Student workspace.', 'Switch to Student mode to use the learning companion. Educator and Parent views do not receive private student conversations.', 'home', 'Return to my view'));
  if (currentAccount().demo) return shell(`<div class="page">${pageTitle('Orbital assistant · locked', 'A guide made of <em>light.</em>', 'Create your own local account to unlock the visual-and-auditory learning companion. The seeded demo identity cannot start private assistant conversations.', actionButton('Create local account ' + icon('arrow'), 'settings'))}<section class="panel assistant-locked"><div class="spectrum-orb spectrum-orb-locked"><span class="orb-ring ring-a"></span><span class="orb-ring ring-b"></span><span class="orb-ring ring-c"></span><span class="orb-core"></span><span class="orb-particle p1"></span><span class="orb-particle p2"></span><span class="orb-particle p3"></span><span class="orb-particle p4"></span><span class="orb-particle p5"></span></div><div><div class="eyebrow">ACCOUNT REQUIRED</div><h2 class="panel-title" style="font-size:24px;margin-top:8px">Unlock your orbital guide.</h2><p class="panel-copy" style="max-width:540px">Create a local account and the assistant will remember this conversation in your browser, use your saved proof context, and read guidance aloud through your device. No microphone recording or voice data leaves this page.</p><div class="assistant-capabilities"><span>VISUAL ORB</span><span>TEXT CHAT</span><span>READ ALOUD</span></div></div></section></div>`);
  const messages = state.assistantMessages.length ? state.assistantMessages : [{ from: 'assistant', text: `Hello ${currentAccount().name}. I’m your COSMOS orbital guide. Ask me about a proof task, your progress, a saved report, or the next useful step.` }];
  return shell(`<div class="page">${pageTitle('Orbital assistant · account active', 'Think with a <em>second signal.</em>', 'A visual-and-auditory learning companion for reflection, evidence planning, and next steps. It guides; it never assigns mastery.', '<span class="badge badge-green">ACCOUNT UNLOCKED</span>')}
    <div class="assistant-layout"><section class="panel assistant-console"><div class="assistant-console-head"><div><div class="panel-kicker">COSMOS / ORBITAL GUIDE</div><h2 class="panel-title">LUMA</h2><p class="panel-copy">A spectrum-of-light interface for your learning signal.</p></div><div class="assistant-status"><span class="status-dot"></span>READY TO RESPOND</div></div><div class="assistant-stage"><div class="spectrum-orb"><span class="orb-ring ring-a"></span><span class="orb-ring ring-b"></span><span class="orb-ring ring-c"></span><span class="orb-core"></span><span class="orb-particle p1"></span><span class="orb-particle p2"></span><span class="orb-particle p3"></span><span class="orb-particle p4"></span><span class="orb-particle p5"></span><span class="orb-particle p6"></span></div><div class="assistant-stage-copy"><span class="small-mono">VISUAL FIELD / 01</span><strong>Listen for the next observable move.</strong><span>Guidance is based on your local proof records and your words.</span></div></div><div class="assistant-messages">${messages.map(message => `<div class="assistant-message ${message.from === 'assistant' ? 'assistant-message-ai' : 'assistant-message-user'}"><div class="assistant-message-label">${message.from === 'assistant' ? 'LUMA / GUIDE' : esc(currentAccount().name.toUpperCase())}</div><p>${esc(message.text)}</p>${message.from === 'assistant' ? `<button class="text-button" data-assistant-speak data-text="${esc(message.text)}">${icon('spark')} Read aloud</button>` : ''}</div>`).join('')}</div>${assistantQuestPanel()}<div class="assistant-quick"><span class="panel-kicker">QUICK SIGNALS</span><div class="assistant-quick-row"><button class="btn btn-ghost" data-assistant-prompt="What should I do next?">Next step</button><button class="btn btn-ghost" data-assistant-prompt="Help me with my photosynthesis proof">Photosynthesis proof</button><button class="btn btn-ghost" data-assistant-prompt="How do I read my progress report?">Read my report</button></div></div><form class="assistant-form" data-assistant-form><label class="sr-only" for="assistant-input">Ask the Orbital Assistant</label><input id="assistant-input" class="input" name="prompt" maxlength="240" required placeholder="Ask LUMA about your learning signal…" /><button class="btn btn-primary" type="submit">Send ${icon('arrow')}</button></form><p class="assistant-footnote">Auditory mode uses your browser’s local speech synthesis. COSMOS does not record or upload your voice.</p></section><aside class="assistant-side"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">What LUMA can do</h2><p class="panel-copy">Support reflection without replacing your judgment.</p></div><span class="badge badge-cyan">LOCAL CONTEXT</span></div><div class="side-list"><div class="side-list-item"><div class="side-list-icon">01</div><div class="side-list-copy"><div class="side-list-title">Frame a proof task</div><div class="side-list-meta">Turn a concept into observable evidence.</div></div></div><div class="side-list-item"><div class="side-list-icon">02</div><div class="side-list-copy"><div class="side-list-title">Read your signal</div><div class="side-list-meta">Connect rubric scores to a next revision.</div></div></div><div class="side-list-item"><div class="side-list-icon">03</div><div class="side-list-copy"><div class="side-list-title">Speak the guidance</div><div class="side-list-meta">Use read-aloud for a hands-free reflection loop.</div></div></div></div></section>${assistantLlmPanel()}<section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Privacy boundary</h2><p class="panel-copy">The assistant is not a surveillance layer.</p></div></div><div class="notice"><strong>Account-scoped and local.</strong> LUMA reads the active account’s saved proof summaries in this browser. It does not infer emotion, make mastery decisions, or retain microphone input.</div></section></aside></div>
  </div>`);
}

function renderDigitalId() {
  if (state.role !== 'student') return shell(roleBoundary('Digital ID belongs to the Student workspace.', 'Student identity and account bridges stay separate from Parent and Educator views. Switch to Student to manage this ID.', 'home', 'Return to my view'));
  if (currentAccount().demo) return shell(`<div class="page">${pageTitle('Digital ID · locked', 'Carry your signal <em>with consent.</em>', 'Create your own local account before creating a Digital ID or bridging with another student account.', actionButton('Create local account ' + icon('arrow'), 'settings'))}<section class="panel digital-locked"><div class="id-hologram"><span></span><strong>ID</strong></div><div><div class="eyebrow">ACCOUNT REQUIRED</div><h2 class="panel-title" style="font-size:24px;margin-top:8px">Your Digital ID starts with you.</h2><p class="panel-copy" style="max-width:520px">The demo identity cannot create a personal image, share a bridge, or expose an account handle. Create a local account first; your ID data will stay in this browser until you explicitly connect it.</p></div></section></div>`);
  const otherAccounts = state.accounts.filter(account => account.id !== state.accountId && !account.demo);
  const avatar = state.digitalId.avatar ? `<img class="digital-avatar" src="${esc(state.digitalId.avatar)}" alt="Chosen Digital ID picture" />` : `<div class="digital-avatar digital-avatar-empty"><span>${esc((state.digitalId.alias || currentAccount().name).slice(0, 2).toUpperCase())}</span></div>`;
  const bridges = state.digitalId.bridges || [];
  return shell(`<div class="page">${pageTitle('Digital ID · student workspace', 'Make your identity <em>portable by consent.</em>', 'Create a learner-controlled ID with a picture of your choice, then bridge it to another local student account without exposing private proof records.', '<span class="badge badge-green">LOCAL · PRIVATE BY DEFAULT</span>')}
    <div class="digital-layout"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Your Digital ID</h2><p class="panel-copy">A learner-chosen alias, image, and stable local handle. No real legal identity is required.</p></div><span class="badge badge-cyan">${esc(state.digitalId.handle)}</span></div><div class="digital-card"><div class="digital-card-visual">${avatar}<div class="digital-orbit"><span></span><span></span><span></span></div></div><div class="digital-card-copy"><div class="panel-kicker">COSMOS LEARNER ID</div><h3>${esc(state.digitalId.alias || currentAccount().name)}</h3><p>${esc(state.digitalId.handle)} · created ${state.digitalId.createdAt || 'not saved yet'}</p><div class="digital-signals"><span>STUDENT ACCOUNT</span><span>CHOICE-OWNED IMAGE</span><span>NO PUBLIC PROFILE</span></div></div></div><div class="field" style="margin-top:18px"><label class="form-label" for="digital-alias">Display alias</label><input id="digital-alias" class="input" data-digital-alias maxlength="48" value="${esc(state.digitalId.alias || currentAccount().name)}" placeholder="Choose the name shown on your ID" /></div><div class="camera-tools"><div class="camera-frame${state.cameraStream ? ' has-camera' : ''}"><video id="camera-preview" autoplay playsinline muted aria-label="Camera preview for Digital ID photo"></video><div class="camera-placeholder">Camera preview appears only after you choose Start camera.</div></div><div class="camera-actions"><button class="btn btn-ghost" data-action="start-camera">Start camera</button><button class="btn btn-primary" data-action="capture-camera">Capture picture</button><button class="btn btn-ghost" data-action="stop-camera">Stop camera</button><label class="btn btn-ghost file-button">Choose picture<input type="file" accept="image/*" data-digital-file /></label><p class="helper">The picture is resized and stored locally for this account. Camera access is requested only after you press Start camera.</p></div></div><div class="form-actions"><span class="helper">Your ID is not an accreditation, public profile, or legal identity document.</span><button class="btn btn-primary" data-action="save-digital-id">Save Digital ID ${icon('check')}</button></div></section><aside class="aside-stack"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Bridge another student</h2><p class="panel-copy">Connect two local accounts with a consented bridge limited to Digital ID summaries.</p></div><span class="badge badge-amber">EXPLICIT CONSENT</span></div>${otherAccounts.length ? `<div class="field"><label class="form-label" for="bridge-target">Student account in this browser</label><select id="bridge-target" class="select" data-bridge-target><option value="">Choose an account</option>${otherAccounts.map(account => `<option value="${account.id}">${esc(account.name)}</option>`).join('')}</select></div><label class="consent-check"><input type="checkbox" data-bridge-consent /><span><strong>I consent to bridge these Digital IDs.</strong><small>Only aliases, chosen pictures, handles, and bridge date are shared in this prototype. Proof drafts, grades, raw notes, and camera data are not shared.</small></span></label><button class="btn btn-primary" data-action="bridge-account">Create consented bridge ${icon('arrow')}</button>` : `<div class="empty"><strong>Create another local Student account first.</strong><br/>Bridging is currently limited to accounts in this browser; no cross-device identity exchange is claimed.</div>`}</section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Active bridges</h2><p class="panel-copy">You can remove a bridge at any time.</p></div><span class="small-mono">${bridges.length} LINKED</span></div>${bridges.length ? `<div class="side-list">${bridges.map(bridge => `<div class="side-list-item"><div class="side-list-icon">↔</div><div class="side-list-copy"><div class="side-list-title">${esc(bridge.name)}</div><div class="side-list-meta">${esc(bridge.handle)} · bridged ${esc(bridge.date)}</div></div><button class="text-button" data-bridge-remove="${bridge.accountId}">Remove</button></div>`).join('')}</div>` : '<div class="empty">No bridges yet. Your Digital ID remains private.</div>'}</section><section class="panel pad"><div class="notice"><strong>Privacy boundary.</strong> Camera permission is browser-controlled. COSMOS stores only the resized picture you choose, locally, and never uploads it in this MVP.</div></section></aside></div>
  </div>`);
}

function renderAtlas() {
  const data = atlasData[state.atlasSubject];
  const subjects = Object.keys(atlasData);
  return shell(`<div class="page">${pageTitle('Learning Atlas · 04', 'A map of <em>possibility.</em>', 'Browse from a broad subject to a specific objective. There are no age gates here; curiosity can move ahead of the pathway.', '<span class="badge badge-cyan">9 DOMAINS SEEDED</span>')}
    <div class="atlas-layout"><section class="panel atlas-nav"><div class="panel-kicker" style="padding:9px 12px 11px">Subjects / disciplines</div>${subjects.map(subject => `<button class="atlas-subject ${state.atlasSubject === subject ? 'selected' : ''}" data-atlas-subject="${esc(subject)}">${esc(subject)}<span>${atlasData[subject].disciplines.length}</span></button>`).join('')}</section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">${esc(state.atlasSubject)}</h2><p class="panel-copy">Select the layer that makes your next question more precise.</p></div><span class="small-mono">ATLAS NODE / ${subjects.indexOf(state.atlasSubject) + 1} OF ${subjects.length}</span></div><div class="hierarchy"><div class="hierarchy-col"><div class="hierarchy-label">Discipline</div>${data.disciplines.map((item, index) => `<div class="hierarchy-item ${index === 0 ? 'selected' : ''}"><strong>${esc(item)}</strong><small>sample discipline node</small></div>`).join('')}</div><div class="hierarchy-col"><div class="hierarchy-label">Concept</div>${data.concepts.map((item, index) => `<div class="hierarchy-item ${index === 0 ? 'selected' : ''}"><strong>${esc(item)}</strong><small>organizing concept</small></div>`).join('')}</div><div class="hierarchy-col"><div class="hierarchy-label">Learning objective</div><div class="hierarchy-item selected"><strong>${esc(data.objective)}</strong><small>objective can become a COSMOS PROOF task</small></div><button class="btn btn-primary" style="margin-top:7px;width:100%" data-route="proof">Use as proof objective ${icon('arrow')}</button></div></div></section></div>
    <div class="grid grid-3 section-space">${[['Observe','Notice patterns before naming them.'],['Understand','Build a model you can explain.'],['Connect','Relate a concept to a wider system.']].map(([title,copy],i) => `<section class="panel pad"><div class="panel-kicker">0${i+1} / lens</div><h2 class="panel-title" style="margin-top:11px">${title}</h2><p class="panel-copy">${copy}</p></section>`).join('')}</div>
  </div>`);
}

function renderPathways() {
  return shell(`<div class="page">${pageTitle('Learning pathways · 05', 'Move at the speed of <em>curiosity.</em>', 'Pathways suggest useful prerequisites without turning age into a gate. Accommodations belong in the plan from the beginning.', actionButton('Browse the Atlas ' + icon('arrow'), 'atlas'))}
    <div class="grid grid-3">${[
      ['01','Living systems / evidence','Explain, model, and test transformations in living systems.','3 / 5 signals','featured'],
      ['02','Source sensemaking','Compare claims, trace evidence, and communicate uncertainty.','2 / 4 signals',''],
      ['03','Computational inquiry','Build small models, inspect errors, and revise the question.','1 / 4 signals','']
    ].map(([number,title,copy,progress,extra]) => `<section class="panel path-card ${extra}"><div class="path-top"><span class="path-number">PATH ${number}</span><span class="badge ${extra ? 'badge-cyan' : 'badge-muted'}">${extra ? 'CURRENT' : 'OPEN'}</span></div><h2 class="path-title">${title}</h2><p class="path-copy">${copy}</p><div class="path-steps">${[0,1,2,3,4].map(i => `<span class="path-step ${i < (extra ? 2 : 1) ? 'done' : i === (extra ? 2 : 1) ? 'current' : ''}"></span>`).join('')}</div><div class="path-foot"><span>${progress}</span><span>Age-flexible</span></div></section>`).join('')}</div>
    <div class="grid grid-2 section-space"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Recommended prerequisites</h2><p class="panel-copy">Suggestions are transparent and can be skipped when the evidence supports it.</p></div></div><div class="side-list">${['Energy vocabulary → systems model','Source claims → reliability criteria','Small test → explain model error'].map((item, i) => `<div class="side-list-item"><div class="side-list-icon">0${i+1}</div><div class="side-list-copy"><div class="side-list-title">${item}</div><div class="side-list-meta">Recommended, not required</div></div></div>`).join('')}</div></section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Accommodations in the plan</h2><p class="panel-copy">The learner decides what makes evidence easier to access.</p></div><span class="badge badge-green">FIRST-CLASS</span></div><div class="side-list">${['Extra processing time for knowledge checks','Speech-to-text or typed explanation','High-contrast / low-motion presentation','Alternative artifact format'].map(item => `<div class="side-list-item"><div class="side-list-icon">✓</div><div class="side-list-copy"><div class="side-list-title">${item}</div><div class="side-list-meta">Can be added without changing the objective</div></div></div>`).join('')}</div></section></div>
  </div>`);
}

function educatorReviewPanel(record) {
  const objectiveData = objectives.find(item => item.id === record.objectiveId) || {};
  const allProficient = hasCompleteRubric(state.scores) && state.scores.every(score => score >= 3);
  return `<section class="panel pad section-space"><div class="panel-header"><div><div class="eyebrow">Active educator review · ${record.id}</div><h2 class="panel-title" style="font-size:18px;margin-top:7px">${esc(record.title)}</h2><p class="panel-copy">${esc(objectiveData.title || record.objectiveId)} · ${esc(record.type)}</p></div><span class="badge ${statusClass(record.status)}">${record.status}</span></div><div class="grid grid-2"><div><div class="panel-kicker">Evidence description</div><p class="panel-copy" style="font-size:12px;margin-top:8px;color:var(--text)">${esc(record.evidence || 'No evidence description recorded.')}</p><div class="callout" style="margin-top:15px"><strong>Human review required.</strong> Selecting Mastered is only enabled when all eight dimensions are at least Proficient and the educator explicitly confirms the record.</div></div><div><label class="form-label" for="review-feedback">Feedback to learner</label><textarea id="review-feedback" class="textarea" data-review-field="feedback" placeholder="Name what is clear, what is uncertain, and the next useful revision.">${esc(state.reviewFeedback)}</textarea></div></div><div style="margin-top:20px"><div class="panel-header"><div><h3 class="panel-title">Review rubric</h3><p class="panel-copy">${allProficient ? 'All dimensions currently meet the mastery threshold.' : 'Some dimensions still need evidence at Proficient or Advanced.'}</p></div><span class="small-mono">${state.scores.filter(score => score >= 3).length}/8 AT THRESHOLD</span></div>${rubricGrid()}</div><div class="form-actions"><button class="btn btn-ghost" data-action="clear-review">Close review</button><div class="form-actions-right"><button class="btn btn-danger" data-action="save-review" data-status="Revision needed">Request revision</button><button class="btn btn-ghost" data-action="save-review" data-status="Reviewed">Mark reviewed</button><button class="btn btn-primary" data-action="save-review" data-status="Mastered" ${allProficient ? '' : 'disabled'}>Confirm mastery ${icon('check')}</button></div></div></section>`;
}

function renderEducator() {
  if (state.role !== 'educator') return shell(roleBoundary('Educator review is a protected view.', 'Switch to Educator to review submissions, write feedback, calibrate scores, and maintain the audit trail.', 'home', 'Return to my view'));
  const reviewRecord = state.records.find(record => record.id === state.reviewRecordId);
  const reviewedCount = state.records.filter(record => record.reviewed || record.assessor?.includes('educator')).length;
  return shell(`<div class="page">${pageTitle('Educator view · 06', 'Review the evidence, <em>not the clock.</em>', 'A human-centered review surface for feedback, calibration, objective design, and an auditable decision trail.', actionButton(icon('plus') + ' Create objective', '', 'btn btn-primary', 'create-objective'))}
    <div class="grid grid-4 section-space">${statCard('Awaiting review', state.records.filter(record => !record.reviewed).length.toString().padStart(2, '0'), 'across 2 pathways', 'amber')} ${statCard('Calibration drift', '0.4', 'within review range', 'violet')} ${statCard('Revision loops', '08', 'last 30 days')} ${statCard('Human reviewed', `${Math.round(reviewedCount / Math.max(state.records.length, 1) * 100)}%`, 'this demo cohort', 'green')}</div>
    <section class="panel pad section-space"><div class="panel-header"><div><h2 class="panel-title">Review queue</h2><p class="panel-copy">Open a record to inspect the evidence, score dimensions, and leave feedback.</p></div><span class="badge badge-amber">DEMO LEARNER</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Submission</th><th>Objective</th><th>Submitted</th><th>Current signal</th><th>Action</th></tr></thead><tbody>${state.records.map(record => `<tr><td><strong>${esc(record.title)}</strong><small>${record.type} · ${record.id}</small></td><td><strong>${record.objectiveId}</strong><small>${esc((objectives.find(o=>o.id===record.objectiveId) || {}).domain || 'Objective')}</small></td><td>${record.date}</td><td><span class="badge ${statusClass(record.status)}">${record.status}</span></td><td><button class="btn btn-ghost" data-review-id="${record.id}" style="min-height:28px;padding:0 9px;font-size:10px">Review ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div></section>
    ${reviewRecord ? educatorReviewPanel(reviewRecord) : '<div class="notice section-space"><strong>Review is active.</strong> Select a submission above to score its evidence, write feedback, and make an explicit educator decision.</div>'}
    <div class="grid grid-2 section-space"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Calibration note</h2><p class="panel-copy">Use shared language to keep scores interpretable across learners.</p></div></div>${rubricGrid()}</section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Audit trail</h2><p class="panel-copy">Every change should be explainable to the learner.</p></div></div><div class="audit"><div class="audit-item"><strong>Review protocol updated</strong> · mastery rule clarified<span class="audit-time">A. Rivera · 31 Oct 2026</span></div><div class="audit-item"><strong>Scores calibrated</strong> · source quality exemplars added<span class="audit-time">Educator circle · 30 Oct 2026</span></div><div class="audit-item"><strong>Accommodation recorded</strong> · typed explanation permitted<span class="audit-time">Demo Learner · 29 Oct 2026</span></div></div></section></div>
  </div>`);
}

function renderSettings() {
  const account = currentAccount();
  return shell(`<div class="page">${pageTitle('Settings & privacy · 07', 'Keep the workspace <em>yours.</em>', 'COSMOS is privacy-first by design. This MVP uses a safe demo identity or local account with managed persistence and a browser-local fallback.', '<span class="badge badge-green">NO ADS · NO SALE OF DATA</span>')}
    <section class="panel pad section-space"><div class="panel-header"><div><h2 class="panel-title">Create your local account</h2><p class="panel-copy">Use a name or alias to save proof progress, reports, and grade bands separately in this browser.</p></div><span class="badge badge-amber">PROTOTYPE ONLY</span></div><form data-account-form><div class="form-row"><div class="field"><label class="form-label" for="account-name">Display name or alias</label><input id="account-name" class="input" name="name" minlength="2" maxlength="48" required placeholder="e.g. Alex Rivera" /></div><div class="field"><label class="form-label" for="account-create-note">Storage boundary</label><div id="account-create-note" class="account-boundary"><strong>Local to this browser</strong><span>No password, email collection, or cross-device sync is implemented in this MVP.</span></div></div></div><div class="form-actions"><span class="helper">Creating an account switches you to a fresh Student workspace. Your records remain scoped to the selected account.</span><button class="btn btn-primary" type="submit">Create local account ${icon('plus')}</button></div></form></section>
    <div class="grid grid-2"><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Role & data boundary</h2><p class="panel-copy">Clear controls for learner and educator contexts.</p></div></div><div class="settings-list"><div class="setting-row"><span class="setting-copy"><strong>Current account</strong><p>${esc(account.name)} · ${account.demo ? 'demo profile' : 'local account'}</p></span><span class="badge badge-cyan">${currentRole().label.toUpperCase()}</span></div><div class="setting-row"><span class="setting-copy"><strong>Educator preview</strong><p>Shows how human review and audit trails work.</p></span><span class="switch"><input type="checkbox" data-setting="educatorPreview" ${state.settings.educatorPreview ? 'checked' : ''}/><span class="switch-track"></span></span></div><div class="setting-row"><span class="setting-copy"><strong>Account-scoped persistence</strong><p>Proof records, reports, and assistant progress ${state.persistenceStatus === 'synced' ? 'sync to the managed COSMOS database.' : 'stay in this browser until database sync is available.'}</p></span><span class="badge ${state.persistenceStatus === 'synced' ? 'badge-green' : 'badge-amber'}">${state.persistenceStatus === 'synced' ? 'DATABASE SYNCED' : state.persistenceStatus === 'syncing' ? 'SYNCING' : 'LOCAL FALLBACK'}</span></div></div></section><section class="panel pad"><div class="panel-header"><div><h2 class="panel-title">Accessibility</h2><p class="panel-copy">Adapt the interface without changing the objective.</p></div></div><div class="settings-list"><div class="setting-row"><span class="setting-copy"><strong>Reduced motion</strong><p>Use instant transitions and no decorative movement.</p></span><span class="switch"><input type="checkbox" data-setting="reducedMotion" ${state.settings.reducedMotion ? 'checked' : ''}/><span class="switch-track"></span></div><div class="setting-row"><span class="setting-copy"><strong>Keyboard navigation</strong><p>All actions are reachable with standard focus order.</p></span><span class="badge badge-green">READY</span></div><div class="setting-row"><span class="setting-copy"><strong>High contrast surfaces</strong><p>Text and status signals are not color-only.</p></span><span class="badge badge-green">READY</span></div></div></section></div>
    <section class="panel pad section-space"><div class="panel-header"><div><h2 class="panel-title">Data controls</h2><p class="panel-copy">Export or remove records for the active local account. There is no public sharing or production authentication in this MVP. Account identity is still prototype-level; add real authentication before production use.</p></div></div><div class="form-actions" style="margin-top:0"><div class="helper">We collect the minimum needed for a proof record: alias, objective, evidence notes, rubric scores, review context, and audit events. No sensitive child data, advertising, facial/voice inference, payments, or public leaderboard.</div><div class="form-actions-right"><button class="btn btn-ghost" data-action="export">${icon('download')} Export</button><button class="btn btn-danger" data-action="clear-data">Delete local records</button></div></div></section>
  </div>`);
}

function renderAbout() {
  return shell(`<div class="page">${pageTitle('About COSMOS ACADEMIA', 'Learning is a <em>living record.</em>', 'COSMOS is a universal learning observatory for children, teens, adults, independent learners, and lifelong researchers.', actionButton('Try the proof workspace ' + icon('arrow'), 'proof'))}
    <section class="panel hero-panel"><div class="hero-copy"><div><div class="hero-kicker">The COSMOS philosophy</div><h2 class="hero-title">Observe → Understand → Connect → <span>Experiment → Create → Contribute</span></h2><p class="hero-text">We believe learning becomes more durable when a person can show what changed in their thinking, make evidence visible, receive human feedback, and revise without shame.</p></div><div class="hero-actions"><button class="btn btn-ghost" data-route="atlas">Explore the Atlas</button><button class="btn btn-ghost" data-route="pathways">See pathways</button></div></div><div class="orbit-scene"><span class="hero-index">ABOUT / SIGNAL 00</span><span class="orbit-node node-a"></span><span class="orbit-node node-b"></span><span class="orbit-node node-c"></span><span class="orbit-node node-d"></span><span class="orbit-core"></span></div></section>
    <div class="grid grid-3 section-space">${[['Evidence-first','Learning is not equated with attendance or time-on-task. The thing that matters is what the evidence makes observable.'],['Human oversight','Rubrics are transparent, uncertainty is visible, and an educator remains accountable for a mastery decision.'],['Universal by default','Age-inclusive pathways, accessibility, and accommodations are part of the learning design—not a later patch.']].map(([title,copy], index) => `<section class="panel pad"><div class="panel-kicker">0${index+1} / principle</div><h2 class="panel-title" style="margin-top:11px">${title}</h2><p class="panel-copy">${copy}</p></section>`).join('')}</div>
    <section class="panel pad section-space"><div class="panel-header"><div><h2 class="panel-title">MVP boundary</h2><p class="panel-copy">A working prototype is honest about what it does and does not claim.</p></div><span class="badge badge-amber">LOCAL DEMO</span></div><p class="panel-copy" style="max-width:760px;font-size:13px">This version supports managed database persistence with a browser-local fallback. It does not provide production authentication, legal identity, external accreditation, cryptographic verification, public sharing, or automated high-stakes decisions. COSMOS PROOF shows the intended evidence and review workflow so it can be tested immediately.</p></section>
  </div>`);
}

function render() {
  state.records = normalizeRecords(state.records);
  if (!['home','proof','assistant','digital-id','reports','portfolio','atlas','pathways','educator','settings','about'].includes(state.route)) state.route = 'home';
  if (state.route !== 'digital-id' && state.cameraStream) { state.cameraStream.getTracks().forEach(track => track.stop()); state.cameraStream = null; }
  const views = { home: renderHome, proof: renderProof, assistant: renderAssistant, 'digital-id': renderDigitalId, reports: renderReports, portfolio: renderPortfolio, atlas: renderAtlas, pathways: renderPathways, educator: renderEducator, settings: renderSettings, about: renderAbout };
  document.querySelector('#app').innerHTML = views[state.route]();
  bindEvents();
}

function speakText(text) { if (!('speechSynthesis' in window)) return showToast('Read aloud unavailable', 'This browser does not expose local speech synthesis.'); window.speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(text); utterance.rate = .96; utterance.pitch = 1.03; utterance.onstart = () => showToast('LUMA speaking', 'Audio stays in your browser.'); window.speechSynthesis.speak(utterance); }
async function startCamera() { if (!navigator.mediaDevices?.getUserMedia) return showToast('Camera unavailable', 'This browser does not expose camera access. You can still choose a picture file.'); try { state.cameraStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: false }); render(); const video = document.querySelector('#camera-preview'); if (video) video.srcObject = state.cameraStream; showToast('Camera ready', 'Frame your picture, then choose Capture picture.'); } catch { showToast('Camera permission needed', 'Camera access was not granted. Choose a picture file instead, or try again.'); } }
function stopCamera() { if (state.cameraStream) state.cameraStream.getTracks().forEach(track => track.stop()); state.cameraStream = null; const video = document.querySelector('#camera-preview'); if (video) video.srcObject = null; render(); }
function imageToDataUrl(fileOrSource) { return new Promise((resolve, reject) => { const image = new Image(); image.onload = () => { const scale = Math.min(1, 640 / Math.max(image.width, image.height)); const canvas = document.createElement('canvas'); canvas.width = Math.max(1, Math.round(image.width * scale)); canvas.height = Math.max(1, Math.round(image.height * scale)); canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height); resolve(canvas.toDataURL('image/jpeg', .82)); }; image.onerror = reject; if (typeof fileOrSource === 'string') image.src = fileOrSource; else { const reader = new FileReader(); reader.onload = () => { image.src = reader.result; }; reader.onerror = reject; reader.readAsDataURL(fileOrSource); } }); }
async function captureCamera() { const video = document.querySelector('#camera-preview'); if (!video?.srcObject) return showToast('Start camera first', 'Choose Start camera before capturing a Digital ID picture.'); const canvas = document.createElement('canvas'); canvas.width = video.videoWidth || 640; canvas.height = video.videoHeight || 480; canvas.getContext('2d').translate(canvas.width, 0); canvas.getContext('2d').scale(-1, 1); canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height); state.digitalId.avatar = await imageToDataUrl(canvas.toDataURL('image/jpeg', .9)); stopCamera(); showToast('Picture captured', 'Review the Digital ID preview, then save it.'); }
function bridgeAccount(targetId) { const target = state.accounts.find(account => account.id === targetId); if (!target || target.demo) return showToast('Bridge unavailable', 'Choose another created Student account in this browser.'); const consent = document.querySelector('[data-bridge-consent]'); if (!consent?.checked) return showToast('Consent required', 'Check the consent box before creating this Digital ID bridge.'); const targetIdData = loadDigitalId(targetId); const bridgeDate = formatDate(); const currentBridge = { accountId: target.id, name: target.name, handle: targetIdData.handle, date: bridgeDate }; state.digitalId.bridges = [...(state.digitalId.bridges || []).filter(bridge => bridge.accountId !== target.id), currentBridge]; saveDigitalId(); targetIdData.bridges = [...(targetIdData.bridges || []).filter(bridge => bridge.accountId !== state.accountId), { accountId: state.accountId, name: currentAccount().name, handle: state.digitalId.handle, date: bridgeDate }]; localStorage.setItem(`cosmos-digital-id-${target.id}`, JSON.stringify(targetIdData)); render(); showToast('Digital ID bridge created', `You are now connected to ${target.name} with consent-limited summaries.`); }
function removeBridge(accountId) { state.digitalId.bridges = (state.digitalId.bridges || []).filter(bridge => bridge.accountId !== accountId); saveDigitalId(); const targetIdData = loadDigitalId(accountId); targetIdData.bridges = (targetIdData.bridges || []).filter(bridge => bridge.accountId !== state.accountId); localStorage.setItem(`cosmos-digital-id-${accountId}`, JSON.stringify(targetIdData)); render(); showToast('Bridge removed', 'The consented Digital ID connection was removed.'); }
async function callFormativeLlm(kind, prompt = '') { const quest = currentQuest(); const record = state.records.find(item => item.objectiveId === quest.id); const response = await fetch('/api/luma-formative', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind, objective: { id: quest.id, domain: quest.domain, title: quest.title }, stage: questStage(record), learnerPrompt: prompt.slice(0, 1200), proof: record ? { status: record.status, evidence: String(record.evidence || '').slice(0, 2400), scoreSignals: (record.scores || []).map(score => score >= 3 ? 'proficient-or-above' : 'developing') } : null }) }); const payload = await response.json().catch(() => ({})); if (!response.ok || !payload.ok) throw new Error(payload.error || 'Formative analysis unavailable'); return payload.formative; }
async function assistantReply(prompt) { if (currentAccount().demo) return; const cleanPrompt = prompt.trim(); if (!cleanPrompt) return; dispatchLearningEvent({ type: 'ASSISTANT_MESSAGE', objectiveId: state.questObjectiveId }); state.assistantMessages.push({ from: 'user', text: cleanPrompt }); saveAssistantMessages(); render(); let reply = assistantResponse(cleanPrompt); if (state.llmConsent) { state.llmPending = true; render(); try { const formative = await callFormativeLlm('dialogue', cleanPrompt); reply = formative.dialogue || formative.nextStep || reply; } catch { reply = `${reply} I could not reach formative AI this time, so I’m using your local curriculum guide instead.`; } state.llmPending = false; } state.assistantMessages.push({ from: 'assistant', text: reply }); saveAssistantMessages(); render(); }
async function runFormativeAnalysis() { if (!state.llmConsent || state.llmPending) return; state.llmPending = true; render(); try { state.lastLlmAnalysis = await callFormativeLlm('analysis'); state.lastLlmAnalysis.createdAt = formatDate(); saveLlmAnalysis(); dispatchLearningEvent({ type: 'FORMATIVE_SIGNAL_READY', objectiveId: state.questObjectiveId }); showToast('Formative signal ready', 'LUMA found strengths, gaps, and a next practice move.'); } catch { showToast('Formative AI unavailable', 'Your local quest guide is still available; no mastery decision was made.'); } finally { state.llmPending = false; render(); } }
async function switchAccount(accountId) { if (!state.accounts.some(account => account.id === accountId)) return; saveRecords(); saveAssistantMessages(); saveDigitalId(); if (serverSyncTimer) { clearTimeout(serverSyncTimer); serverSyncTimer = null; } state.remoteReady = false; state.accountId = accountId; saveActiveAccount(); state.records = loadRecords(accountId); state.assistantMessages = loadAssistantMessages(); state.digitalId = loadDigitalId(); state.avatarState = loadAvatarState(); state.questObjectiveId = loadQuestObjective(); state.llmConsent = loadLlmConsent(); state.lastLlmAnalysis = loadLlmAnalysis(); state.role = 'student'; saveRole(); state.route = 'home'; state.reviewRecordId = null; state.reviewFeedback = ''; if (location.hash !== '#home') location.hash = 'home'; render(); await hydrateFromServer(accountId); showToast('Account switched', `Now viewing ${currentAccount().name}'s workspace.`); }
function createLocalAccount(name) { const cleanName = name.trim().replace(/\s+/g, ' '); if (cleanName.length < 2) return showToast('Account not created', 'Use at least two characters for a display name or alias.'); const id = `acct-${Date.now()}`; state.accounts = [{ id, name: cleanName, createdAt: formatDate(), demo: false }, ...state.accounts]; state.accountId = id; state.records = []; state.assistantMessages = []; state.digitalId = defaultDigitalId(id); state.avatarState = loadAvatarState(id); state.questObjectiveId = 'BIO-04'; state.llmConsent = false; state.lastLlmAnalysis = null; saveAccounts(); saveActiveAccount(); saveRecords(); saveAssistantMessages(); saveDigitalId(); saveQuestObjective(); saveLlmConsent(); saveLlmAnalysis(); state.role = 'student'; saveRole(); state.route = 'home'; if (location.hash !== '#home') location.hash = 'home'; render(); showToast('Local account created', `${cleanName}'s progress will now be saved in this browser.`); }
function bindEvents() {
  const cameraVideo = document.querySelector('#camera-preview'); if (cameraVideo && state.cameraStream) cameraVideo.srcObject = state.cameraStream;
  const roleSwitch = document.querySelector('[data-role-switch]'); if (roleSwitch) roleSwitch.addEventListener('change', event => { state.role = event.target.value; saveRole(); state.route = 'home'; state.reviewRecordId = null; state.reviewFeedback = ''; if (location.hash !== '#home') location.hash = 'home'; render(); showToast('Role switched', `Now viewing the ${currentRole().label} prototype lens.`); });
  const accountSwitch = document.querySelector('[data-account-switch]'); if (accountSwitch) accountSwitch.addEventListener('change', event => switchAccount(event.target.value));
  const accountForm = document.querySelector('[data-account-form]'); if (accountForm) accountForm.addEventListener('submit', event => { event.preventDefault(); createLocalAccount(new FormData(accountForm).get('name') || ''); });
  const assistantForm = document.querySelector('[data-assistant-form]'); if (assistantForm) assistantForm.addEventListener('submit', event => { event.preventDefault(); assistantReply(new FormData(assistantForm).get('prompt') || ''); });
  const llmConsent = document.querySelector('[data-llm-consent]'); if (llmConsent) llmConsent.addEventListener('change', event => { state.llmConsent = event.target.checked; saveLlmConsent(); render(); });
  document.querySelectorAll('[data-assistant-prompt]').forEach(el => el.addEventListener('click', () => assistantReply(el.dataset.assistantPrompt || '')));
  document.querySelectorAll('[data-assistant-speak]').forEach(el => el.addEventListener('click', () => speakText(el.dataset.text || '')));
  const assistantObjective = document.querySelector('[data-assistant-objective]'); if (assistantObjective) assistantObjective.addEventListener('change', event => { state.questObjectiveId = event.target.value; state.objectiveId = event.target.value; saveQuestObjective(); dispatchLearningEvent({ type: 'OBJECTIVE_SELECTED', objectiveId: event.target.value }); render(); });
  document.querySelectorAll('[data-quest-id]').forEach(el => el.addEventListener('click', () => { state.questObjectiveId = el.dataset.questId; state.objectiveId = el.dataset.questId; saveQuestObjective(); dispatchLearningEvent({ type: 'OBJECTIVE_SELECTED', objectiveId: el.dataset.questId }); render(); }));
  document.querySelectorAll('[data-bridge-remove]').forEach(el => el.addEventListener('click', () => removeBridge(el.dataset.bridgeRemove)));
  const digitalFile = document.querySelector('[data-digital-file]'); if (digitalFile) digitalFile.addEventListener('change', async event => { const file = event.target.files?.[0]; if (!file) return; try { state.digitalId.avatar = await imageToDataUrl(file); render(); showToast('Picture ready', 'Review the Digital ID preview, then save it locally.'); } catch { showToast('Picture error', 'That picture could not be prepared in this browser.'); } });
  document.querySelectorAll('[data-route]').forEach(el => el.addEventListener('click', () => { if (el.dataset.objective) state.objectiveId = el.dataset.objective; routeTo(el.dataset.route); }));
  document.querySelectorAll('[data-atlas-subject]').forEach(el => el.addEventListener('click', () => { state.atlasSubject = el.dataset.atlasSubject; render(); }));
  const objectiveSelect = document.querySelector('[data-change="objective"]'); if (objectiveSelect) objectiveSelect.addEventListener('change', event => { state.objectiveId = event.target.value; state.proofAnswers = {}; state.checkResult = null; state.proofEvidence = { type: 'Explanation', description: '', file: '' }; state.proofStep = 1; render(); });
  document.querySelectorAll('[data-answer]').forEach(el => el.addEventListener('change', event => { state.proofAnswers[event.target.dataset.answer] = event.target.value; }));
  document.querySelectorAll('[data-proof-next]').forEach(el => el.addEventListener('click', () => { const nextStep = Number(el.dataset.proofNext); if (nextStep === 2) { const answered = state.proofAnswers.q1 && state.proofAnswers.q2; const correct = state.proofAnswers.q1 === 'b' && state.proofAnswers.q2 === 'b'; state.checkResult = { correct, message: answered ? (correct ? 'Both answers align with the core idea. Use the evidence step to show how you know.' : 'The evidence task is a chance to revise the model. A strong answer connects stored chemical energy to a source or testable diagram.') : 'You can continue, but consider returning to answer both questions before you submit.' }; dispatchLearningEvent({ type: 'KNOWLEDGE_CHECK_COMPLETED', objectiveId: state.objectiveId, correct }); } else if (nextStep === 1) dispatchLearningEvent({ type: 'KNOWLEDGE_CHECK_STARTED', objectiveId: state.objectiveId }); state.proofStep = nextStep; render(); }));
  document.querySelectorAll('[data-proof-field]').forEach(el => el.addEventListener('input', event => { state.proofEvidence[event.target.dataset.proofField] = event.target.value; }));
  const fileInput = document.querySelector('[data-proof-file]'); if (fileInput) fileInput.addEventListener('change', event => { state.proofEvidence.file = event.target.files?.[0]?.name || ''; render(); });
  document.querySelectorAll('[data-score-index]').forEach(el => el.addEventListener('click', () => { state.scores[Number(el.dataset.scoreIndex)] = Number(el.dataset.score); render(); }));
  document.querySelectorAll('[data-setting]').forEach(el => el.addEventListener('change', event => { const key = event.target.dataset.setting; if (key === 'shareConsent') state.shareConsent = event.target.checked; else state.settings[key] = event.target.checked; if (key === 'reducedMotion') document.documentElement.classList.toggle('reduce-motion', event.target.checked); render(); }));
  document.querySelectorAll('[data-review-id]').forEach(el => el.addEventListener('click', () => openReview(el.dataset.reviewId)));
  document.querySelectorAll('[data-review-field]').forEach(el => el.addEventListener('input', event => { state.reviewFeedback = event.target.value; }));
  document.querySelectorAll('[data-action]').forEach(el => el.addEventListener('click', () => handleAction(el.dataset.action, el)));
}
function openReview(recordId) { const record = state.records.find(item => item.id === recordId); if (!record) return; state.reviewRecordId = recordId; state.scores = [...normalizeRecord(record).scores]; state.reviewFeedback = record.feedback || ''; render(); }
function saveReview(status) { if (state.role !== 'educator') return; if (status === 'Mastered' && (!hasCompleteRubric(state.scores) || !state.scores.every(score => score >= 3))) return showToast('Review incomplete', 'All eight dimensions need valid Proficient or Advanced ratings before a human can confirm mastery.'); const record = state.records.find(item => item.id === state.reviewRecordId); if (!record) return; record.scores = [...state.scores]; record.feedback = state.reviewFeedback || 'Reviewed with no additional note.'; record.assessor = 'A. Rivera · educator'; record.reviewed = true; record.status = status; record.audit = [...(record.audit || []), `${status} by educator · ${formatDate()}`]; saveRecords(); dispatchLearningEvent({ type: 'HUMAN_REVIEW_RECORDED', objectiveId: record.objectiveId, status }); showToast('Review saved', `${record.id} is now ${status.toLowerCase()} with an explicit educator decision.`); }
function handleAction(action, element) {
  if (action === 'run-formative-analysis') { runFormativeAnalysis(); return; }
  if (action === 'start-camera') { startCamera(); return; }
  if (action === 'stop-camera') { stopCamera(); return; }
  if (action === 'capture-camera') { captureCamera(); return; }
  if (action === 'save-digital-id') { const alias = document.querySelector('[data-digital-alias]')?.value?.trim(); if (!alias) return showToast('Alias required', 'Choose the name or alias that should appear on your Digital ID.'); state.digitalId.alias = alias; state.digitalId.createdAt = state.digitalId.createdAt || formatDate(); saveDigitalId(); showToast('Digital ID saved', 'Your chosen picture and alias are stored locally for this account.'); return; }
  if (action === 'bridge-account') { bridgeAccount(document.querySelector('[data-bridge-target]')?.value); return; }
  if (action === 'save-review') { saveReview(element?.dataset.status || 'Reviewed'); return; }
  if (action === 'clear-review') { state.reviewRecordId = null; state.reviewFeedback = ''; render(); return; }
  if (action === 'submit-proof') {
    const obj = objective();
    const record = { id: `P-${105 + state.records.length}`, learner: currentAccount().name, objectiveId: obj.id, title: state.proofEvidence.description ? `${obj.id} · ${state.proofEvidence.type}` : `${obj.id} · proof attempt`, type: state.proofEvidence.type, evidence: state.proofEvidence.description || 'Submitted from the proof workspace.', scores: [...state.scores], assessor: 'Pending human review', feedback: 'Awaiting educator feedback. Mastery is never assigned automatically.', date: formatDate(), status: 'Submitted', demo: currentAccount().demo, audit: [`Submitted evidence · ${formatDate()}`, 'Awaiting human review'] };
    state.records = [record, ...state.records]; saveRecords(); dispatchLearningEvent({ type: 'PROOF_SUBMITTED', objectiveId: obj.id }); state.proofStep = 1; showToast('Proof submitted', 'Your evidence is recorded locally and queued for human review.'); return;
  }
  if (action === 'export' || action === 'export-reports') {
    const payload = JSON.stringify({ account: currentAccount(), exportedAt: new Date().toISOString(), prototypeGradeNotice: 'Grade bands are rubric-derived demo signals, not accreditation.', records: state.records.map(record => ({ ...record, gradeBand: gradeBand(record), rubricAverage: assessedRatings(record.scores).length ? avg(record.scores) : null })) }, null, 2); const blob = new Blob([payload], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'cosmos-saved-reports.json'; a.click(); URL.revokeObjectURL(url); showToast('Reports exported', 'A local JSON copy of this account’s saved reports was downloaded.'); return;
  }
  if (action === 'clear-data') { state.records = []; saveRecords(); showToast('Local records deleted', 'The demo portfolio is now empty.'); return; }
  if (action === 'create-objective') { showToast('Objective builder', 'In this MVP, objective creation is represented by the seeded Atlas nodes.'); return; }
  if (action === 'search') { showToast('Search', 'Atlas search is ready to be expanded from the seeded objective graph.'); }
}

window.addEventListener('hashchange', () => { state.route = location.hash.replace('#', '') || 'home'; render(); });
